// ─────────────────────────────────────────────────────────────────────
// Node: Build Run Context & Authenticate     Mode: Run Once for All Items
// Repo: n8n-hubspot-user-permission-offboarding-sanitizer · dhRobin Systems
// Works for both triggers. Scheduled runs scan recent deactivations; the
// webhook accepts an explicit offboarding request (HRIS / IT ticket) and
// must carry the shared secret. Fails closed.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

let crypto = null;
try { crypto = require('crypto'); } catch (error) { crypto = null; }

const SANDBOX_MODE = flag('SANDBOX_MODE', true);
const DRY_RUN = flag('DRY_RUN', true);
const SECRET_HEADER = env('WEBHOOK_SECRET_HEADER', 'x-webhook-secret').toLowerCase();
const SANDBOX_FIXTURE_SECRET = 'sandbox-fictional-secret-not-for-production';
const EXPECTED_SECRET = env('WEBHOOK_SHARED_SECRET', '') || (SANDBOX_MODE ? SANDBOX_FIXTURE_SECRET : '');

const safeEqual = (a, b) => {
  if (typeof a !== 'string' || typeof b !== 'string' || !a || !b) return false;
  if (crypto) {
    return crypto.timingSafeEqual(crypto.createHash('sha256').update(a).digest(), crypto.createHash('sha256').update(b).digest());
  }
  let diff = a.length ^ b.length;
  for (let i = 0; i < Math.max(a.length, b.length); i++) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return diff === 0;
};

let runId;
try { runId = 'offb_' + crypto.randomUUID(); } catch (error) { runId = 'offb_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 10); }

const input = $input.first() ? $input.first().json : {};
const isWebhook = input && typeof input.headers === 'object' && input.headers !== null;

const run = {
  runId,
  startedAt: new Date().toISOString(),
  mode: SANDBOX_MODE ? 'sandbox' : DRY_RUN ? 'dry_run' : 'live',
  sandboxMode: SANDBOX_MODE,
  dryRun: DRY_RUN,
  trigger: isWebhook ? 'webhook' : 'schedule',
  hubspotApiBase: env('HUBSPOT_API_BASE_URL', 'https://api.hubapi.com'),
  accepted: true,
  rejectReason: null,
  request: null,
};

const normaliseRequest = (body) => {
  const users = Array.isArray(body && body.users) ? body.users.slice(0, 50) : [];
  return {
    requestId: body && body.requestId ? String(body.requestId).slice(0, 80) : null,
    effectiveDate: body && body.effectiveDate ? String(body.effectiveDate).slice(0, 40) : null,
    requestedBy: body && body.requestedBy ? String(body.requestedBy).slice(0, 120) : null,
    users: users
      .map((u) => ({
        email: u && u.email ? String(u.email).trim().toLowerCase() : null,
        userId: u && u.userId != null ? String(u.userId) : null,
        ownerId: u && u.ownerId != null ? String(u.ownerId) : null,
      }))
      .filter((u) => u.email || u.userId || u.ownerId),
  };
};

if (isWebhook) {
  const headers = {};
  for (const [k, v] of Object.entries(input.headers || {})) headers[String(k).toLowerCase()] = Array.isArray(v) ? String(v[0]) : String(v);
  if (!EXPECTED_SECRET) { run.accepted = false; run.rejectReason = 'shared_secret_not_configured'; }
  else if (!safeEqual(headers[SECRET_HEADER] || '', EXPECTED_SECRET)) { run.accepted = false; run.rejectReason = 'shared_secret_mismatch'; }
  else {
    let body = input.body;
    if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
    run.request = normaliseRequest(body);
    if (!run.request.users.length) { run.accepted = false; run.rejectReason = 'no_users_in_request'; }
  }
} else {
  // Scheduled run: optional standing list of people being offboarded.
  const emails = csv('OFFBOARDING_USER_EMAILS').map((e) => e.toLowerCase());
  const ids = csv('OFFBOARDING_USER_IDS');
  const fixtureRequest = SANDBOX_MODE && input.sandboxFixtures ? input.sandboxFixtures.offboardingRequest : null;
  run.request = fixtureRequest
    ? normaliseRequest(fixtureRequest)
    : { requestId: null, effectiveDate: null, requestedBy: 'scheduled_scan', users: [...emails.map((email) => ({ email })), ...ids.map((userId) => ({ userId }))] };
}

const fixtures = SANDBOX_MODE && input && typeof input.sandboxFixtures === 'object' ? input.sandboxFixtures : null;

return [{ json: { kind: run.accepted ? 'run' : 'rejected', run, sandboxFixtures: fixtures } }];

// ─────────────────────────────────────────────────────────────────────
// Node: Load Sandbox Directory               Mode: Run Once for All Items
// Emits the fictional users/owners directory in the same shape that the
// live "Collect Directory" node produces. Relative dates are resolved so
// the fixtures never go stale.
// ─────────────────────────────────────────────────────────────────────
const { run, sandboxFixtures } = $input.first().json;

const resolveDates = (value) => {
  if (typeof value === 'string') {
    let m = value.match(/^SANDBOX_DAYS_AGO:(\d{1,4})$/);
    if (m) return new Date(Date.now() - Number(m[1]) * 86400000).toISOString();
    m = value.match(/^SANDBOX_DAYS_FROM_NOW:(\d{1,4})$/);
    if (m) return new Date(Date.now() + Number(m[1]) * 86400000).toISOString().slice(0, 10);
    return value;
  }
  if (Array.isArray(value)) return value.map(resolveDates);
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, resolveDates(v)]));
  return value;
};

if (!sandboxFixtures || !sandboxFixtures.directory) {
  return [{ json: { kind: 'directory', run, directory: { ok: false, reason: 'sandbox_fixtures_missing', users: [], activeOwners: [], archivedOwners: [] } } }];
}

const directory = resolveDates(sandboxFixtures.directory);
return [{
  json: {
    kind: 'directory',
    run,
    directory: { ok: true, source: 'sandbox_fixtures', users: directory.users || [], activeOwners: directory.activeOwners || [], archivedOwners: directory.archivedOwners || [] },
    sandboxEvidence: resolveDates(sandboxFixtures.evidence || {}),
    sandboxPriorReports: sandboxFixtures.priorReports || [],
  },
}];

// ─────────────────────────────────────────────────────────────────────
// Node: Collect Directory                    Mode: Run Once for All Items
// Merges the paginated Users API and Owners API (active + archived) pages.
// Any failed call marks the directory as unavailable. The scan reports
// that as a security finding instead of silently returning "all clear".
// ─────────────────────────────────────────────────────────────────────
const run = $('Build Run Context & Authenticate').first().json.run;

const collect = (nodeName) => {
  const pages = $(nodeName).all();
  const results = [];
  let error = null;
  for (const p of pages) {
    const body = p.json || {};
    if (body.error) error = typeof body.error === 'string' ? body.error : body.error.message || 'request_failed';
    else if (Array.isArray(body.results)) results.push(...body.results);
    else if (body.status === 'error') error = body.category || body.message || 'request_failed';
  }
  return { results, error, pages: pages.length };
};

const users = collect('List HubSpot Users');
const activeOwners = collect('List Active Owners');
const archivedOwners = collect('List Archived Owners');
const errors = [
  users.error ? `users: ${users.error}` : null,
  activeOwners.error ? `active owners: ${activeOwners.error}` : null,
  archivedOwners.error ? `archived owners: ${archivedOwners.error}` : null,
].filter(Boolean).map((e) => String(e).replace(/Bearer\s+[A-Za-z0-9\-._~+\/]+=*/gi, 'Bearer [REDACTED]').slice(0, 200));

return [{
  json: {
    kind: 'directory',
    run,
    directory: {
      ok: errors.length === 0,
      reason: errors.join('; ') || null,
      source: 'hubspot_api',
      pages: { users: users.pages, activeOwners: activeOwners.pages, archivedOwners: archivedOwners.pages },
      users: users.results,
      activeOwners: activeOwners.results,
      archivedOwners: archivedOwners.results,
    },
  },
}];

// ─────────────────────────────────────────────────────────────────────
// Node: Identify Departing Users             Mode: Run Once for All Items
// Classifies accounts that need an offboarding audit:
//   deactivated          archived owner (userId null, userIdIncludingInactive set)
//   pending_offboarding  named in a webhook request / OFFBOARDING_USER_* but still active
//   suspended_or_unlinked active owner whose user no longer appears in the Users API
//   unassigned_user      active user with no role and no team (limbo account)
// Also prepares fallback-owner candidates from the same primary team.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const LOOKBACK_DAYS = Math.max(1, num('DEACTIVATION_LOOKBACK_DAYS', 30));
const INCLUDE_ALL_ARCHIVED = flag('INCLUDE_ALL_ARCHIVED_OWNERS', false);
const INCLUDE_UNASSIGNED = flag('INCLUDE_UNASSIGNED_USERS', true);
const MAX_DEPARTING = Math.max(1, num('MAX_DEPARTING_USERS_PER_RUN', 25));
const IGNORE_OWNER_IDS = new Set(csv('IGNORE_OWNER_IDS'));

const src = $input.first().json;
const run = src.run;
const dir = src.directory || { ok: false };

if (!dir.ok) {
  return [{ json: { kind: 'scan_error', run, error: { stage: 'directory', reason: dir.reason || 'directory_unavailable' } } }];
}

const nowMs = Date.now();
const cutoff = nowMs - LOOKBACK_DAYS * 86400000;
const usersById = new Map((dir.users || []).map((u) => [String(u.id), u]));
const activeOwners = (dir.activeOwners || []).filter((o) => o && o.type !== 'QUEUE' && o.archived !== true);
const activeOwnerByUserId = new Map(activeOwners.filter((o) => o.userId != null).map((o) => [String(o.userId), o]));
const ownerName = (o) => [o.firstName, o.lastName].filter(Boolean).join(' ').trim() || o.email || `Owner ${o.id}`;
const primaryTeam = (o) => (Array.isArray(o.teams) ? o.teams.find((t) => t.primary) || o.teams[0] : null) || null;

const departing = new Map(); // ownerId -> record
const add = (owner, status, extra = {}) => {
  if (!owner || IGNORE_OWNER_IDS.has(String(owner.id))) return;
  const key = String(owner.id);
  if (departing.has(key)) {
    const existing = departing.get(key);
    existing.signals = [...new Set([...existing.signals, status])];
    return;
  }
  const team = primaryTeam(owner);
  departing.set(key, {
    ownerId: key,
    userId: owner.userId != null ? String(owner.userId) : owner.userIdIncludingInactive != null ? String(owner.userIdIncludingInactive) : null,
    email: owner.email ? String(owner.email).toLowerCase() : null,
    name: ownerName(owner),
    status,
    signals: [status],
    archived: owner.archived === true,
    ownerUpdatedAt: owner.updatedAt || null,
    primaryTeam: team ? { id: String(team.id), name: team.name || null } : null,
    ...extra,
  });
};

// 1 · Deactivated users (archived owners)
let skippedOutsideLookback = 0;
for (const o of dir.archivedOwners || []) {
  if (!o || o.type === 'QUEUE') continue;
  const updated = Date.parse(o.updatedAt || '');
  if (!INCLUDE_ALL_ARCHIVED && (!Number.isFinite(updated) || updated < cutoff)) { skippedOutsideLookback++; continue; }
  add(o, 'deactivated');
}

// 2 · Explicit offboarding requests (webhook or standing list)
const requested = (run.request && run.request.users) || [];
const unmatchedRequests = [];
for (const r of requested) {
  const owner =
    (r.ownerId && (activeOwners.find((o) => String(o.id) === r.ownerId) || (dir.archivedOwners || []).find((o) => String(o.id) === r.ownerId))) ||
    (r.userId && (activeOwnerByUserId.get(r.userId) || (dir.archivedOwners || []).find((o) => String(o.userIdIncludingInactive) === r.userId))) ||
    (r.email && (activeOwners.find((o) => String(o.email || '').toLowerCase() === r.email) || (dir.archivedOwners || []).find((o) => String(o.email || '').toLowerCase() === r.email)));
  if (!owner) { unmatchedRequests.push(r.email ? `${r.email[0]}***@${r.email.split('@')[1] || ''}` : r.userId || r.ownerId); continue; }
  add(owner, owner.archived ? 'deactivated' : 'pending_offboarding', { requested: true });
}

// 3 · Active owners whose user record is gone (suspended / removed / unlinked)
for (const o of activeOwners) {
  if (o.userId != null && !usersById.has(String(o.userId))) add(o, 'suspended_or_unlinked');
}

// 4 · Active users with no role and no team
if (INCLUDE_UNASSIGNED) {
  for (const u of dir.users || []) {
    const noRole = !Array.isArray(u.roleIds) || u.roleIds.length === 0;
    const noTeam = !u.primaryTeamId && (!Array.isArray(u.secondaryTeamIds) || u.secondaryTeamIds.length === 0);
    if (noRole && noTeam && u.superAdmin !== true) {
      const owner = activeOwnerByUserId.get(String(u.id));
      if (owner) add(owner, 'unassigned_user');
    }
  }
}

// Fallback candidates: active owners whose user is active and not departing
const departingIds = new Set(departing.keys());
const eligibleFallbacks = activeOwners
  .filter((o) => !departingIds.has(String(o.id)) && o.userId != null && usersById.has(String(o.userId)))
  .map((o) => ({ ownerId: String(o.id), name: ownerName(o), teamIds: (o.teams || []).map((t) => String(t.id)) }))
  .sort((a, b) => a.name.localeCompare(b.name));

const STATUS_ORDER = { deactivated: 0, pending_offboarding: 1, suspended_or_unlinked: 2, unassigned_user: 3 };
const list = [...departing.values()].sort((a, b) => STATUS_ORDER[a.status] - STATUS_ORDER[b.status]);
const truncated = list.length > MAX_DEPARTING;

const summary = {
  activeUsers: (dir.users || []).length,
  activeOwners: activeOwners.length,
  archivedOwners: (dir.archivedOwners || []).length,
  archivedOutsideLookback: skippedOutsideLookback,
  lookbackDays: LOOKBACK_DAYS,
  departingFound: list.length,
  truncated,
  unmatchedRequests,
};

if (list.length === 0) {
  return [{ json: { kind: 'no_departures', run, directorySummary: summary } }];
}

return list.slice(0, MAX_DEPARTING).map((d) => ({
  json: {
    kind: 'departing',
    run,
    departing: d,
    fallbackCandidates: eligibleFallbacks.filter((f) => d.primaryTeam && f.teamIds.includes(d.primaryTeam.id)).slice(0, 5),
    allFallbackOwnerIds: eligibleFallbacks.map((f) => f.ownerId),
    directorySummary: summary,
    sandboxEvidence: src.sandboxEvidence ? src.sandboxEvidence[d.ownerId] || null : undefined,
    sandboxPriorReports: src.sandboxPriorReports,
  },
}));

// ─────────────────────────────────────────────────────────────────────
// Node: Load Sandbox Evidence                Mode: Run Once for All Items
// Attaches fictional CRM/sequence evidence to each departing user and adds
// the fictional workflow definitions, in the exact shape that Collect
// Evidence produces in live mode.
// ─────────────────────────────────────────────────────────────────────
const items = $input.all().map((i) => i.json);
const empty = { ok: true, total: 0, sample: [] };
const out = items.map((d) => {
  const e = d.sandboxEvidence || {};
  return {
    json: {
      ...d,
      sandboxEvidence: undefined,
      evidence: {
        deals: e.deals || empty,
        tasks: e.tasks || empty,
        tickets: e.tickets || empty,
        sequenceContacts: e.sequenceContacts || empty,
        ownedSequences: e.ownedSequences || empty,
      },
    },
  };
});

const fixtures = $('Load Sandbox Directory').first().json;
const defs = (fixtures.sandboxEvidence && fixtures.sandboxEvidence.__workflowDefinitions) || [];
out.push({
  json: {
    kind: 'workflow_definitions',
    ok: true,
    scanned: defs.length,
    failed: 0,
    totalListed: defs.length,
    truncated: false,
    listError: null,
    definitions: defs.map((d) => ({ id: String(d.id), name: d.name, isEnabled: d.isEnabled === true, definition: d })),
  },
});
return out;

// ─────────────────────────────────────────────────────────────────────
// Node: Build CRM Search Jobs                Mode: Run Once for All Items
// Four read-only CRM searches per departing owner:
//   deals    open deals owned by the rep
//   tasks    tasks not completed
//   tickets  tickets not closed
//   contacts contacts owned by the rep that are currently in a sequence
// Each search returns `total` plus up to SEARCH_SAMPLE_LIMIT records.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const SAMPLE = Math.min(100, Math.max(1, num('SEARCH_SAMPLE_LIMIT', 25)));
const DEAL_CLOSED_STAGES = csv('DEAL_CLOSED_STAGE_IDS');
const TICKET_CLOSED_STAGES = csv('TICKET_CLOSED_STAGE_IDS');
const SEQUENCE_PROPERTY = env('CONTACT_SEQUENCE_ENROLLED_PROPERTY', 'hs_sequences_is_enrolled');

const owner = (id) => ({ propertyName: 'hubspot_owner_id', operator: 'EQ', value: String(id) });
const jobs = [];

$input.all().forEach(({ json }, index) => {
  const id = json.departing.ownerId;
  const dealOpen = DEAL_CLOSED_STAGES.length
    ? { propertyName: 'dealstage', operator: 'NOT_IN', values: DEAL_CLOSED_STAGES }
    : { propertyName: 'hs_is_closed', operator: 'EQ', value: 'false' };
  const ticketOpen = TICKET_CLOSED_STAGES.length
    ? { propertyName: 'hs_pipeline_stage', operator: 'NOT_IN', values: TICKET_CLOSED_STAGES }
    : { propertyName: 'closed_date', operator: 'NOT_HAS_PROPERTY' };
  const specs = [
    { jobType: 'deals', objectType: 'deals', filters: [owner(id), dealOpen], properties: ['dealname', 'amount', 'closedate', 'dealstage', 'pipeline'], sorts: [{ propertyName: 'closedate', direction: 'ASCENDING' }] },
    { jobType: 'tasks', objectType: 'tasks', filters: [owner(id), { propertyName: 'hs_task_status', operator: 'NEQ', value: 'COMPLETED' }], properties: ['hs_task_subject', 'hs_timestamp', 'hs_task_status', 'hs_task_priority'], sorts: [{ propertyName: 'hs_timestamp', direction: 'ASCENDING' }] },
    { jobType: 'tickets', objectType: 'tickets', filters: [owner(id), ticketOpen], properties: ['subject', 'hs_ticket_priority', 'hs_pipeline_stage', 'createdate'], sorts: [{ propertyName: 'createdate', direction: 'ASCENDING' }] },
    { jobType: 'sequence_contacts', objectType: 'contacts', filters: [owner(id), { propertyName: SEQUENCE_PROPERTY, operator: 'EQ', value: 'true' }], properties: ['hs_object_id', SEQUENCE_PROPERTY], sorts: [] },
  ];
  for (const s of specs) {
    jobs.push({
      json: {
        departingIndex: index,
        ownerId: id,
        jobType: s.jobType,
        objectType: s.objectType,
        // Contact samples are IDs only: no names or emails leave HubSpot.
        searchBody: { filterGroups: [{ filters: s.filters }], properties: s.properties, sorts: s.sorts, limit: SAMPLE },
      },
    });
  }
});

return jobs;

// ─────────────────────────────────────────────────────────────────────
// Node: Build Sequence Lookups               Mode: Run Once for All Items
// GET /automation/v4/sequences requires a userId, so one lookup per
// departing user. Always emits at least one item so the chain continues;
// placeholder items are ignored by Collect Evidence.
// ─────────────────────────────────────────────────────────────────────
const departing = $('Departing Users Found?').all();
const out = departing
  .map(({ json }, index) => ({ json: { departingIndex: index, ownerId: json.departing.ownerId, userId: json.departing.userId, placeholder: !json.departing.userId } }));
return out.length ? out : [{ json: { departingIndex: -1, ownerId: null, userId: '0', placeholder: true } }];

// ─────────────────────────────────────────────────────────────────────
// Node: Build Workflow Scan Jobs             Mode: Run Once for All Items
// The v4 list only returns key fields, so each workflow definition is
// fetched and scanned for references to the departing users. Enabled
// workflows first, capped by MAX_WORKFLOWS_TO_SCAN.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const MAX = Math.max(1, num('MAX_WORKFLOWS_TO_SCAN', 300));
const INCLUDE_DISABLED = flag('SCAN_DISABLED_WORKFLOWS', true);

const flows = [];
let listError = null;
for (const page of $input.all()) {
  const body = page.json || {};
  if (body.error) listError = typeof body.error === 'string' ? body.error : body.error.message || 'flows_list_failed';
  if (Array.isArray(body.results)) flows.push(...body.results);
}

const selected = flows
  .filter((f) => f && f.id != null && (INCLUDE_DISABLED || f.isEnabled === true))
  .sort((a, b) => Number(b.isEnabled === true) - Number(a.isEnabled === true))
  .slice(0, MAX);

if (!selected.length) {
  return [{ json: { flowId: '0', placeholder: true, listError: listError ? String(listError).slice(0, 200) : null, totalListed: flows.length } }];
}
return selected.map((f) => ({
  json: { flowId: String(f.id), isEnabled: f.isEnabled === true, name: f.name || null, placeholder: false, totalListed: flows.length, truncated: flows.length > MAX, listError: null },
}));

// ─────────────────────────────────────────────────────────────────────
// Node: Collect Evidence                     Mode: Run Once for All Items
// Pairs every HTTP response with the job that produced it (n8n keeps item
// order per node) and emits:
//   • one `departing` item per user with CRM + sequence evidence
//   • one `workflow_definitions` item shared by the scanner
// ─────────────────────────────────────────────────────────────────────
const departing = $('Departing Users Found?').all().map((i) => i.json);
const searchJobs = $('Build CRM Search Jobs').all().map((i) => i.json);
const searchRes = $('Run CRM Orphan Searches').all().map((i) => i.json);
const seqJobs = $('Build Sequence Lookups').all().map((i) => i.json);
const seqRes = $('Fetch Owned Sequences').all().map((i) => i.json);
const flowJobs = $('Build Workflow Scan Jobs').all().map((i) => i.json);
const flowRes = $input.all().map((i) => i.json);

const clean = (s) => String(s || '').replace(/Bearer\s+[A-Za-z0-9\-._~+\/]+=*/gi, 'Bearer [REDACTED]').slice(0, 200);
const failure = (r) => ({ ok: false, statusCode: Number(r && r.statusCode) || null, reason: clean((r && r.body && (r.body.category || r.body.message)) || (r && r.error && (r.error.message || r.error)) || 'request_failed') });

const shapeRecord = (jobType, rec) => {
  const p = rec.properties || {};
  if (jobType === 'deals') return { id: String(rec.id), name: p.dealname || null, amount: p.amount != null && p.amount !== '' ? Number(p.amount) : null, closeDate: p.closedate || null, stage: p.dealstage || null, pipeline: p.pipeline || null };
  if (jobType === 'tasks') return { id: String(rec.id), subject: p.hs_task_subject || null, dueAt: p.hs_timestamp || null, status: p.hs_task_status || null, priority: p.hs_task_priority || null };
  if (jobType === 'tickets') return { id: String(rec.id), subject: p.subject || null, priority: p.hs_ticket_priority || null, stage: p.hs_pipeline_stage || null, createdAt: p.createdate || null };
  return { id: String(rec.id) }; // contacts: ID only
};

const out = departing.map((d, index) => {
  const evidence = {};
  searchJobs.forEach((job, i) => {
    if (job.departingIndex !== index) return;
    const r = searchRes[i] || {};
    const key = job.jobType === 'sequence_contacts' ? 'sequenceContacts' : job.jobType;
    if (Number(r.statusCode) === 200 && r.body) {
      const results = Array.isArray(r.body.results) ? r.body.results : [];
      evidence[key] = { ok: true, total: Number(r.body.total ?? results.length), sample: results.map((rec) => shapeRecord(job.jobType, rec)) };
    } else {
      evidence[key] = failure(r);
    }
  });
  const si = seqJobs.findIndex((j) => j.departingIndex === index);
  if (si === -1 || seqJobs[si].placeholder) {
    evidence.ownedSequences = { ok: false, statusCode: null, reason: 'no_user_id_for_owner' };
  } else {
    const r = seqRes[si] || {};
    if (Number(r.statusCode) === 200 && r.body) {
      const results = Array.isArray(r.body.results) ? r.body.results : [];
      evidence.ownedSequences = { ok: true, total: Number(r.body.total ?? results.length), sample: results.slice(0, 25).map((s) => ({ id: String(s.id), name: s.name || null })) };
    } else {
      evidence.ownedSequences = failure(r);
    }
  }
  return { json: { ...d, evidence } };
});

const definitions = [];
let flowErrors = 0;
flowJobs.forEach((job, i) => {
  if (job.placeholder) return;
  const r = flowRes[i] || {};
  if (Number(r.statusCode) === 200 && r.body) definitions.push({ id: job.flowId, name: r.body.name || job.name || `Workflow ${job.flowId}`, isEnabled: r.body.isEnabled ?? job.isEnabled, definition: r.body });
  else flowErrors++;
});
const placeholder = flowJobs.find((j) => j.placeholder);

out.push({
  json: {
    kind: 'workflow_definitions',
    ok: !(placeholder && placeholder.listError) && flowErrors === 0,
    scanned: definitions.length,
    failed: flowErrors,
    totalListed: flowJobs.length ? flowJobs[0].totalListed : 0,
    truncated: flowJobs.length ? !!flowJobs[0].truncated : false,
    listError: placeholder ? placeholder.listError : null,
    definitions,
  },
});
return out;

// ─────────────────────────────────────────────────────────────────────
// Node: Orphaned Asset & Data Scanner        Mode: Run Once for All Items
// Cross-references each departing user against:
//   workflows   definitions that reference their owner ID, user ID or email
//   sequences   contacts they own that are currently enrolled + sequences they own
//   deals       open deals (closing soon / high value flagged)
//   tasks       open tasks (overdue flagged)
//   tickets     open tickets (high priority flagged)
// and assigns a risk score and tier.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const CLOSING_SOON_DAYS = Math.max(1, num('DEAL_CLOSING_SOON_DAYS', 30));
const HIGH_VALUE = Math.max(0, num('HIGH_VALUE_DEAL_AMOUNT', 50000));
const HIGH_PRIORITY_TICKETS = new Set(csv('HIGH_PRIORITY_TICKET_VALUES', 'HIGH,URGENT').map((s) => s.toUpperCase()));

const all = $input.all().map((i) => i.json);
const defsItem = all.find((i) => i.kind === 'workflow_definitions') || { ok: false, definitions: [], scanned: 0 };
const departing = all.filter((i) => i.kind === 'departing');
const nowMs = Date.now();

// ── Workflow reference scan ───────────────────────────────────────────
const REF_KEY = /(owner|user|assign|recipient|notif|rotat|sender|cc|to_email|email)/i;
const OWNER_CONTEXT = /hubspot_owner_id|owner/i;
const classify = (path, ctx) => {
  const t = `${path} ${ctx}`.toLowerCase();
  if (t.includes('enrollmentcriteria') || t.includes('reenrollment')) return 'enrollment_filter';
  if (/rotat/.test(t)) return 'owner_rotation';
  if (/notif|recipient|cc|to_email/.test(t)) return 'internal_notification';
  if (/task/.test(t)) return 'task_assignment';
  if (/owner/.test(t)) return 'owner_assignment';
  return 'user_reference';
};

function scanDefinition(def, ids, email) {
  const refs = [];
  const walk = (node, path, ctx, ownerCtx) => {
    if (refs.length >= 20) return;
    if (Array.isArray(node)) { node.forEach((v, i) => walk(v, `${path}[${i}]`, ctx, ownerCtx)); return; }
    if (node && typeof node === 'object') {
      const strings = Object.values(node).filter((v) => typeof v === 'string').join(' ');
      const childCtx = `${ctx} ${strings}`.slice(-300);
      const childOwnerCtx = ownerCtx || OWNER_CONTEXT.test(strings);
      for (const [k, v] of Object.entries(node)) {
        if (['id', 'revisionId', 'portalId', 'createdAt', 'updatedAt', 'actionId', 'nextActionId'].includes(k) && path === '') continue;
        walk(v, path ? `${path}.${k}` : k, childCtx, childOwnerCtx);
      }
      return;
    }
    if (node === null || node === undefined) return;
    const value = String(node);
    if (email && value.toLowerCase().includes(email)) { refs.push({ path, kind: 'email_reference' }); return; }
    if (ids.has(value) && (REF_KEY.test(path) || ownerCtx)) refs.push({ path, kind: classify(path, ctx) });
  };
  walk(def, '', '', false);
  return refs;
}

const count = (e) => (e && e.ok ? Number(e.total || 0) : 0);
const out = [];

for (const d of departing) {
  const person = d.departing;
  const e = d.evidence || {};
  const ids = new Set([person.ownerId, person.userId].filter(Boolean).map(String));
  const email = person.email || null;

  const evidenceErrors = [];
  for (const [k, v] of Object.entries(e)) if (!v || !v.ok) evidenceErrors.push({ source: k, statusCode: v ? v.statusCode : null, reason: v ? v.reason : 'missing' });
  if (!defsItem.ok) evidenceErrors.push({ source: 'workflows', statusCode: null, reason: defsItem.listError || `${defsItem.failed || 0} definitions failed to load` });

  // Workflows
  const workflowHits = [];
  for (const wf of defsItem.definitions || []) {
    const refs = scanDefinition(wf.definition, ids, email);
    if (refs.length) workflowHits.push({ id: wf.id, name: wf.name, isEnabled: wf.isEnabled === true, references: refs, kinds: [...new Set(refs.map((r) => r.kind))] });
  }
  const enabledWorkflows = workflowHits.filter((w) => w.isEnabled);
  const disabledWorkflows = workflowHits.filter((w) => !w.isEnabled);

  // Deals
  const dealSample = (e.deals && e.deals.sample) || [];
  const soonCutoff = nowMs + CLOSING_SOON_DAYS * 86400000;
  const closingSoon = dealSample.filter((x) => { const t = Date.parse(x.closeDate || ''); return Number.isFinite(t) && t <= soonCutoff; });
  const highValue = dealSample.filter((x) => Number.isFinite(x.amount) && x.amount >= HIGH_VALUE);
  const sampleAmount = dealSample.reduce((s, x) => s + (Number.isFinite(x.amount) ? x.amount : 0), 0);

  // Tasks & tickets
  const taskSample = (e.tasks && e.tasks.sample) || [];
  const overdue = taskSample.filter((x) => { const t = Date.parse(x.dueAt || ''); return Number.isFinite(t) && t < nowMs; });
  const ticketSample = (e.tickets && e.tickets.sample) || [];
  const highTickets = ticketSample.filter((x) => HIGH_PRIORITY_TICKETS.has(String(x.priority || '').toUpperCase()));

  const findings = {
    workflows: { enabled: enabledWorkflows, disabled: disabledWorkflows, scanned: defsItem.scanned || 0, truncated: !!defsItem.truncated },
    sequenceContacts: { total: count(e.sequenceContacts), sampleIds: ((e.sequenceContacts && e.sequenceContacts.sample) || []).map((x) => x.id).slice(0, 10) },
    ownedSequences: { total: count(e.ownedSequences), sample: (e.ownedSequences && e.ownedSequences.sample) || [] },
    deals: { total: count(e.deals), closingSoon, highValue, sampleAmount, sampleSize: dealSample.length, sample: dealSample.slice(0, 10) },
    tasks: { total: count(e.tasks), overdue: overdue.length, overdueSampleOnly: taskSample.length < count(e.tasks), sample: taskSample.slice(0, 10) },
    tickets: { total: count(e.tickets), highPriority: highTickets, sample: ticketSample.slice(0, 10) },
  };

  // Risk score (documented in README §5)
  let score = 0;
  score += enabledWorkflows.length * 25;
  score += disabledWorkflows.length * 3;
  if (findings.sequenceContacts.total > 0) score += 20 + Math.min(20, Math.ceil(findings.sequenceContacts.total / 5));
  score += closingSoon.length * 10 + highValue.length * 10;
  score += Math.min(20, findings.deals.total * 2);
  score += Math.min(10, overdue.length);
  score += highTickets.length * 5 + Math.min(10, findings.tickets.total);
  score += Math.min(5, Math.ceil(findings.tasks.total / 5));
  score += findings.ownedSequences.total > 0 ? 3 : 0;
  if (person.status === 'pending_offboarding') score += 5; // access still live

  let tier = score >= 60 ? 'critical' : score >= 30 ? 'high' : score >= 10 ? 'medium' : score > 0 ? 'low' : 'none';
  if (evidenceErrors.length && (tier === 'none' || tier === 'low')) tier = 'medium'; // incomplete scan is never "clean"

  out.push({ json: { ...d, evidence: undefined, findings, evidenceErrors, risk: { score, tier } } });
}

return out;

// ─────────────────────────────────────────────────────────────────────
// Node: Reassignment Checklist Generator     Mode: Run Once for All Items
// Builds one prioritised audit report per departing user:
//   P0 · today      live automation and revenue at risk
//   P1 · 3 days     open pipeline, customer tickets, overdue work
//   P2 · 7 days     housekeeping (open tasks, owned sequences, disabled workflows)
// Resolves a recommended fallback owner, fingerprints the findings and
// suppresses unchanged reports inside REPORT_COOLDOWN_HOURS (scheduled runs).
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const SANDBOX_MODE = flag('SANDBOX_MODE', true);
const DRY_RUN = flag('DRY_RUN', true);
const PERSIST = !SANDBOX_MODE && !DRY_RUN;
const COOLDOWN_HOURS = Math.max(1, num('REPORT_COOLDOWN_HOURS', 72));
const NOTIFY_ON_CLEAN = flag('NOTIFY_ON_CLEAN', false);
const DEFAULT_FALLBACK = env('DEFAULT_FALLBACK_OWNER_ID', '');
const PORTAL = env('HUBSPOT_PORTAL_ID', 'YOUR_HUBSPOT_PORTAL_ID');
const APP = env('HUBSPOT_APP_BASE_URL', 'https://app.hubspot.com').replace(/\/+$/, '');
let FALLBACK_MAP = {};
try { FALLBACK_MAP = JSON.parse(env('FALLBACK_OWNER_MAP', '{}')) || {}; } catch (error) { FALLBACK_MAP = {}; }

const items = $input.all().map((i) => i.json);
const nowMs = Date.now();
const run = items.length ? items[0].run : {};
const isWebhook = run && run.trigger === 'webhook';

// ── Report ledger (dedupe) ────────────────────────────────────────────
const staticData = $getWorkflowStaticData('global');
let ledger;
if (PERSIST) {
  staticData.hsOffboardingSanitizer = staticData.hsOffboardingSanitizer || { version: 1, reports: {} };
  ledger = staticData.hsOffboardingSanitizer.reports;
} else if (SANDBOX_MODE) {
  ledger = {};
  const prior = (items.find((i) => i.sandboxPriorReports) || {}).sandboxPriorReports || [];
  for (const p of prior) ledger[String(p.ownerId)] = { fingerprint: p.fingerprint, at: nowMs - Number(p.hoursAgo || 0) * 3600000 };
} else {
  ledger = JSON.parse(JSON.stringify((staticData.hsOffboardingSanitizer && staticData.hsOffboardingSanitizer.reports) || {}));
}
for (const [k, v] of Object.entries(ledger)) if (!v || nowMs - v.at > 30 * 86400000) delete ledger[k];

const links = {
  users: `${APP}/settings/${encodeURIComponent(PORTAL)}/users`,
  deals: `${APP}/contacts/${encodeURIComponent(PORTAL)}/objects/0-3/views/all/list`,
  tasks: `${APP}/contacts/${encodeURIComponent(PORTAL)}/objects/0-27/views/all/list`,
  tickets: `${APP}/contacts/${encodeURIComponent(PORTAL)}/objects/0-5/views/all/list`,
  contacts: `${APP}/contacts/${encodeURIComponent(PORTAL)}/objects/0-1/views/all/list`,
  sequences: `${APP}/sequences/${encodeURIComponent(PORTAL)}`,
  workflow: (id) => `${APP}/workflows/${encodeURIComponent(PORTAL)}/platform/flow/${encodeURIComponent(id)}/edit`,
};
const fmtMoney = (n) => (Number.isFinite(n) ? n.toLocaleString('en-US', { maximumFractionDigits: 0 }) : 'n/a');

function resolveFallback(d) {
  const valid = new Set(d.allFallbackOwnerIds || []);
  const teamId = d.departing.primaryTeam ? d.departing.primaryTeam.id : null;
  if (teamId && FALLBACK_MAP[teamId]) {
    const id = String(FALLBACK_MAP[teamId]);
    return valid.has(id) ? { ownerId: id, name: null, source: 'team_fallback_map' } : { ownerId: id, name: null, source: 'team_fallback_map', warning: 'mapped fallback owner is not an active user' };
  }
  const candidate = (d.fallbackCandidates || [])[0];
  if (candidate) return { ownerId: candidate.ownerId, name: candidate.name, source: 'same_primary_team_suggestion', note: 'Suggestion only: confirm with the team lead.' };
  if (DEFAULT_FALLBACK) return valid.has(DEFAULT_FALLBACK) ? { ownerId: DEFAULT_FALLBACK, name: null, source: 'default_fallback_owner' } : { ownerId: DEFAULT_FALLBACK, name: null, source: 'default_fallback_owner', warning: 'default fallback owner is not an active user' };
  return { ownerId: null, name: null, source: 'manual_selection_required' };
}

const out = [];
for (const d of items) {
  if (d.kind === 'scan_error') {
    const key = '__scan_error__';
    const prev = ledger[key];
    const suppressed = !isWebhook && prev && nowMs - prev.at < 6 * 3600000;
    if (!suppressed) ledger[key] = { fingerprint: 'scan_error', at: nowMs };
    out.push({ json: { kind: 'scan_error', run, route: suppressed ? 'suppressed' : 'notify', notify: !suppressed, report: { title: 'Offboarding scan could not read the HubSpot user directory', tier: 'critical', error: d.error } } });
    continue;
  }
  if (d.kind === 'no_departures') {
    out.push({ json: { kind: 'no_departures', run, route: NOTIFY_ON_CLEAN ? 'notify' : 'clean', notify: NOTIFY_ON_CLEAN, report: { title: 'No departing HubSpot users found', tier: 'none', directorySummary: d.directorySummary } } });
    continue;
  }

  const p = d.departing;
  const f = d.findings;
  const fallback = resolveFallback(d);
  const owner = fallback.ownerId ? `owner ${fallback.ownerId}${fallback.name ? ` (${fallback.name})` : ''}` : 'a fallback owner (choose manually)';
  const checklist = [];
  const push = (priority, assetType, count, title, action, link, sample) => { if (count > 0) checklist.push({ id: `${p.ownerId}:${assetType}:${priority}`, priority, assetType, count, title, action, recommendedOwner: fallback, hubspotLink: link, sample: sample || [] }); };

  // P0
  for (const wf of f.workflows.enabled) {
    push('P0', 'workflow', wf.references.length, `Active workflow references this user: ${wf.name}`,
      `Replace the user in ${wf.kinds.join(', ').replace(/_/g, ' ')} with ${owner}. Rotations and notifications that point at a deactivated user fail or skip silently.`,
      links.workflow(wf.id), wf.references.slice(0, 5).map((r) => `${r.kind}: ${r.path}`));
  }
  push('P0', 'sequence_enrollment', f.sequenceContacts.total, `${f.sequenceContacts.total} owned contacts are still enrolled in sequences`,
    `Unenroll or pause these sequence enrollments before the user's inbox and calendar are disconnected, then decide with ${owner} whether to re-enroll.`, links.contacts, f.sequenceContacts.sampleIds.map((id) => `contact ${id}`));
  const urgentDeals = [...new Map([...f.deals.closingSoon, ...f.deals.highValue].map((x) => [x.id, x])).values()];
  push('P0', 'deal_at_risk', urgentDeals.length, `${urgentDeals.length} open deals closing soon or high value`,
    `Reassign hubspot_owner_id to ${owner} today and brief them before the next customer touchpoint.`, links.deals,
    urgentDeals.slice(0, 5).map((x) => `${x.name || x.id} · ${fmtMoney(x.amount)} · close ${x.closeDate || 'n/a'}`));
  if (p.status === 'pending_offboarding') {
    checklist.push({ id: `${p.ownerId}:access:P0`, priority: 'P0', assetType: 'user_access', count: 1, title: 'User is still active in HubSpot', action: 'Deactivate the user (or remove their seat) on the effective date, after ownership is transferred. Check that their private app tokens and integrations are revoked.', recommendedOwner: fallback, hubspotLink: links.users, sample: [] });
  }
  // P1
  push('P1', 'open_deals', Math.max(0, f.deals.total - urgentDeals.length), `${Math.max(0, f.deals.total - urgentDeals.length)} other open deals`, `Bulk-reassign hubspot_owner_id to ${owner} with a saved view filtered on this owner.`, links.deals, f.deals.sample.filter((x) => !urgentDeals.find((u) => u.id === x.id)).slice(0, 5).map((x) => `${x.name || x.id} · ${fmtMoney(x.amount)}`));
  push('P1', 'open_tickets', f.tickets.total, `${f.tickets.total} open tickets${f.tickets.highPriority.length ? ` (${f.tickets.highPriority.length} high priority)` : ''}`, `Reassign to ${owner} or the support queue. Handle high-priority tickets first and tell the customers who their new contact is.`, links.tickets, f.tickets.sample.slice(0, 5).map((x) => `${x.subject || x.id} · ${x.priority || 'no priority'}`));
  push('P1', 'overdue_tasks', f.tasks.overdue, `${f.tasks.overdue} overdue tasks${f.tasks.overdueSampleOnly ? ' (counted from sample)' : ''}`, `Reassign to ${owner} or close them if they're no longer relevant.`, links.tasks, f.tasks.sample.filter((x) => Date.parse(x.dueAt || '') < nowMs).slice(0, 5).map((x) => `${x.subject || x.id} · due ${x.dueAt || 'n/a'}`));
  // P2
  push('P2', 'open_tasks', Math.max(0, f.tasks.total - f.tasks.overdue), `${Math.max(0, f.tasks.total - f.tasks.overdue)} other open tasks`, `Reassign to ${owner}.`, links.tasks, []);
  push('P2', 'owned_sequences', f.ownedSequences.total, `${f.ownedSequences.total} sequences owned by this user`, `Clone or share these sequences with ${owner} if they're still used, so the templates aren't lost.`, links.sequences, f.ownedSequences.sample.slice(0, 5).map((s) => s.name || s.id));
  for (const wf of f.workflows.disabled) {
    push('P2', 'disabled_workflow', wf.references.length, `Disabled workflow still references this user: ${wf.name}`, 'Update the reference before anyone turns this workflow back on.', links.workflow(wf.id), wf.references.slice(0, 3).map((r) => `${r.kind}: ${r.path}`));
  }
  for (const err of d.evidenceErrors || []) {
    checklist.push({ id: `${p.ownerId}:scan_gap:${err.source}`, priority: 'P1', assetType: 'scan_gap', count: 1, title: `Could not check ${err.source}`, action: `Review ${err.source} manually: the API returned ${err.statusCode || 'an error'} (${err.reason || 'unknown'}).`, recommendedOwner: fallback, hubspotLink: links.users, sample: [] });
  }

  const order = { P0: 0, P1: 1, P2: 2 };
  checklist.sort((a, b) => order[a.priority] - order[b.priority]);

  const fingerprint = `deals:${f.deals.total}|tasks:${f.tasks.total}|tickets:${f.tickets.total}|seqContacts:${f.sequenceContacts.total}|sequences:${f.ownedSequences.total}|workflows:${f.workflows.enabled.length + f.workflows.disabled.length}`;
  const prev = ledger[p.ownerId];
  let route;
  if (d.risk.tier === 'none') route = NOTIFY_ON_CLEAN ? 'notify' : 'clean';
  else if (!isWebhook && prev && prev.fingerprint === fingerprint && nowMs - prev.at < COOLDOWN_HOURS * 3600000) route = 'suppressed';
  else route = 'notify';
  if (route === 'notify') ledger[p.ownerId] = { fingerprint, at: nowMs };

  const groups = { P0: checklist.filter((c) => c.priority === 'P0'), P1: checklist.filter((c) => c.priority === 'P1'), P2: checklist.filter((c) => c.priority === 'P2') };
  out.push({
    json: {
      kind: 'report',
      run,
      route,
      notify: route === 'notify',
      suppression: route === 'suppressed' ? { reason: 'unchanged_since_last_report', hoursSinceLastReport: Math.round((nowMs - prev.at) / 3600000), cooldownHours: COOLDOWN_HOURS } : null,
      report: {
        title: `Offboarding audit · ${p.name}`,
        person: { ownerId: p.ownerId, userId: p.userId, name: p.name, emailMasked: p.email ? `${p.email[0]}***@${p.email.split('@')[1]}` : null, status: p.status, signals: p.signals, primaryTeam: p.primaryTeam, ownerUpdatedAt: p.ownerUpdatedAt, requested: !!p.requested },
        tier: d.risk.tier,
        score: d.risk.score,
        fingerprint,
        fallbackOwner: fallback,
