// Pairs each parent-task response with its report and emits one sub-task
// request per checklist item, linked with parent_id.
// ─────────────────────────────────────────────────────────────────────
const reports = $('Create Todoist Tasks?').all().map((i) => i.json);
const parents = $input.all().map((i) => i.json);
const out = [];
reports.forEach((rep, index) => {
  const res = parents[index] || {};
  const ok = Number(res.statusCode) >= 200 && Number(res.statusCode) < 300 && res.body && res.body.id;
  if (!ok || !rep.todoistPlan) return;
  rep.todoistPlan.subtasks.forEach((sub, n) => {
    out.push({ json: { reportIndex: index, subtaskIndex: n, requestId: `${rep.run.runId}:${rep.report.person.ownerId}:${n}`, body: { ...sub, parent_id: String(res.body.id) } } });
  });
});
return out.length ? out : [{ json: { noSubtasks: true } }];

// ─────────────────────────────────────────────────────────────────────
// Node: Summarize Todoist Delivery           Mode: Run Once for All Items
// One delivery record per report: parent task ID, sub-tasks created/failed.
// Task IDs are kept; task contents are not repeated in the audit log.
// ─────────────────────────────────────────────────────────────────────
const reports = $('Create Todoist Tasks?').all().map((i) => i.json);
const parents = $('Create Todoist Parent Task').all().map((i) => i.json);
const subJobs = $('Build Todoist Sub-tasks').all().map((i) => i.json);
let subRes = [];
try { subRes = $('Create Todoist Sub-tasks').all().map((i) => i.json); } catch (error) { subRes = []; }

return reports.map((rep, index) => {
  const parent = parents[index] || {};
  const parentOk = Number(parent.statusCode) >= 200 && Number(parent.statusCode) < 300 && parent.body && parent.body.id;
  let created = 0;
  let failed = 0;
  subJobs.forEach((job, i) => {
    if (job.noSubtasks || job.reportIndex !== index) return;
    const r = subRes[i] || {};
    if (Number(r.statusCode) >= 200 && Number(r.statusCode) < 300) created++;
    else failed++;
  });
  return {
    json: {
      ...rep,
      todoistPlan: undefined,
      delivery: {
        todoist: {
          mode: 'live',
          simulated: false,
          ok: !!parentOk && failed === 0,
          parentTaskId: parentOk ? String(parent.body.id) : null,
          parentStatus: Number(parent.statusCode) || null,
          subtasksCreated: created,
          subtasksFailed: failed,
          hint: !parentOk && Number(parent.statusCode) === 401 ? 'check TODOIST_API_TOKEN' : !parentOk && Number(parent.statusCode) === 410 ? 'endpoint retired: confirm the current Todoist API version' : null,
        },
      },
    },
  };
});

