    if (!Array.isArray(store.hsOffboardingAudit)) store.hsOffboardingAudit = [];
    store.hsOffboardingAudit.push(record);
    if (store.hsOffboardingAudit.length > RING_SIZE) store.hsOffboardingAudit.splice(0, store.hsOffboardingAudit.length - RING_SIZE);
  } catch (error) { /* static data unavailable in some manual runs */ }
}

return { json: record };

// ─────────────────────────────────────────────────────────────────────
// Node: Sanitized Error Handler              Mode: Run Once for All Items
// Fed by the Error Trigger when this workflow is its own Error Workflow.
// Drops stack traces and request options, redacts secrets, and emits a
// safe alert record (and optionally a minimal Slack notice).
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);
const KNOWN_SECRETS = ['HUBSPOT_ACCESS_TOKEN', 'SLACK_WEBHOOK_URL', 'TODOIST_API_TOKEN', 'WEBHOOK_SHARED_SECRET']
  .map((k) => env(k, '')).filter((v) => v.length >= 8);
const SECRET_KEY = /(authorization|token|secret|password|passwd|api[-_]?key|cookie|signature|webhook[-_]?url)/i;
const redactString = (input) => {
  let s = String(input ?? '');
  for (const secret of KNOWN_SECRETS) s = s.split(secret).join('[REDACTED]');
  return s
    .replace(/Bearer\s+[A-Za-z0-9\-._~+\/]+=*/gi, 'Bearer [REDACTED]')
    .replace(/\bpat-[a-z0-9]{2,6}-[A-Za-z0-9-]{8,}\b/gi, '[REDACTED_HUBSPOT_TOKEN]')
    .replace(/https:\/\/hooks\.slack\.com\/[^\s"']+/gi, '[REDACTED_SLACK_WEBHOOK]')
    .replace(/\bxox[abposr]-[A-Za-z0-9-]+/g, '[REDACTED_SLACK_TOKEN]')
    .replace(/\b[a-f0-9]{40}\b/g, '[REDACTED_40_HEX_TOKEN]')
    .replace(/([?&](?:hapikey|api_key|apikey|token|key|secret)=)[^&\s"']+/gi, '$1[REDACTED]')
    .replace(/\b([A-Za-z0-9._%+-])[A-Za-z0-9._%+-]*@([A-Za-z0-9.-]+\.[A-Za-z]{2,})\b/g, '$1***@$2')
    .slice(0, 1000);
};
const redact = (value, depth = 0) => {
  if (depth > 7) return '[TRUNCATED]';
  if (value === null || value === undefined) return value ?? null;
  if (typeof value === 'string') return redactString(value);
  if (Array.isArray(value)) return value.slice(0, 60).map((v) => redact(v, depth + 1));
  if (typeof value === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(value)) out[k] = SECRET_KEY.test(k) ? '[REDACTED]' : redact(v, depth + 1);
    return out;
  }
  return value;
};
const maskEmail = (email) => {
  const s = String(email || '');
  const at = s.indexOf('@');
  return at > 0 ? `${s[0]}***@${s.slice(at + 1).toLowerCase()}` : null;
};

const SANDBOX_MODE = flag('SANDBOX_MODE', true);
const DRY_RUN = flag('DRY_RUN', true);

return $input.all().map(({ json }) => {
  const execution = json.execution || {};
  const error = execution.error || (json.trigger && json.trigger.error) || {};
  const alert = {
    alertType: 'hs_offboarding_sanitizer_execution_error',
    at: new Date().toISOString(),
    workflow: { id: json.workflow ? json.workflow.id : null, name: redactString(json.workflow ? json.workflow.name : '') },
    execution: { id: execution.id || null, mode: execution.mode || null, retryOf: execution.retryOf || null },
    lastNodeExecuted: execution.lastNodeExecuted || null,
    errorName: redactString(error.name || 'Error'),
    errorMessage: redactString(error.message || 'unknown error').slice(0, 300),
    nextStep: 'Open the execution in n8n (restricted access) and check the node named in lastNodeExecuted.',
  };
  try { console.error(`[hs-offboarding:error] ${JSON.stringify(alert)}`); } catch (e) { /* best effort */ }
  const notify = !SANDBOX_MODE && !DRY_RUN && env('SLACK_WEBHOOK_URL', '') !== '' && flag('SLACK_NOTIFY_ON_MONITOR_ERROR', true);
  return {
    json: {
      ...alert,
      notify,
      slackMessage: {
        text: `Offboarding sanitizer execution failed at ${alert.lastNodeExecuted || 'unknown node'}`,
        blocks: [
          { type: 'header', text: { type: 'plain_text', text: '⚠️ Offboarding sanitizer execution failed', emoji: true } },
          { type: 'section', text: { type: 'mrkdwn', text: `*Node:* ${alert.lastNodeExecuted || 'unknown'}\n*Error:* ${alert.errorName}: ${alert.errorMessage}` } },
          { type: 'context', elements: [{ type: 'mrkdwn', text: `Execution \`${alert.execution.id || 'n/a'}\` · offboarding audits are paused until this is fixed` }] },
        ],
      },
    },
  };
});
